/*selectMasterWmPgPrewarhsngDlvryRegList_Check_Yn*/

		SELECT
		    DECODE(COUNT(*), 0, 'Y', 'N') AS CHECK_CNT
		FROM
		    KEP_BEFORE_STOCKED_WMSIVDT /* 선입고 물류센터 송장테이블 */
		WHERE 1=1
		AND INV_NO = #{INV_NO}
		AND INV_SEQ = #{INV_SEQ}
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}
		AND STATUS <> 'D'
		AND DELIVERY_QTY  <> 0 /* 배송이 진행된 경우 */

mapper.update:
/*updateMasterWmPgPrewarhsngDlvryReg_KEP_BEFORE_STOCKED_IVDT*/
UPDATE KEP_BEFORE_STOCKED_IVDT A /* 선입고송장상세 */ SET CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD') , CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MMSS') , GR_QTY = NVL((SELECT SUM(B.INV_QTY) FROM WMSIVDT B WHERE B.WAREHOUSE_CODE = #{WAREHOUSE_CODE} AND A.BUYER = B.BUYER AND A.INV_NO = B.S_INV_NO AND A.INV_SEQ = B.S_INV_SEQ AND B.STATUS <> 'D') ,0)
, DELIVERY_QTY = NVL(INV_QTY, 0) /* 물류센터배송수량 */ , DELIVERY_USER_ID = #{st_user_id} /* 물류센터배송입력자 */ , DELIVERY_DATE = TO_CHAR(SYSDATE,'YYYYMMDD') WHERE 1=1 AND BUYER = #{BUYER_CODE} AND BS_NO = #{BS_NO}

/*updateMasterWmPgPrewarhsngDlvryReg_KEP_BEFORE_STOCKED_MNG*/

		UPDATE KEP_BEFORE_STOCKED_MNG A /* 선입고관리 */
		SET A.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
		  , A.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MMSS')
		  , A.DI_QTY = NVL((SELECT SUM(B.DELIVERY_QTY)
		                      FROM KEP_BEFORE_STOCKED_WMSIVDT B
		                     WHERE B.WAREHOUSE_CODE = #{WAREHOUSE_CODE}
		                       AND A.BUYER = B.BUYER
		                       AND A.BS_NO = B.BS_NO
		                       AND B.STATUS <> 'D'),0)

		WHERE 1=1
		AND A.BUYER = #{BUYER_CODE}
		AND A.BS_NO = #{BS_NO}
